      className={cn(
        "flex flex-col gap-1 px-6 pt-6 last:pb-6 has-data-[slot=card-action]:grid has-data-[slot=card-action]:grid-cols-[minmax(0,1fr)_fit-content(50%)] has-data-[slot=card-action]:gap-x-4",
        className,
      )}
      {...props}
