export const fieldDescriptionStyles =
  "text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]";
export const fieldErrorStyles =
  "text-xs leading-5 text-destructive [overflow-wrap:anywhere]";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-3 focus:ring-ring/50 invalid:border-destructive invalid:ring-3 invalid:ring-destructive/20 invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive/30 [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import { CheckIcon, MinusIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { createContext, type ReactNode, useContext, useState } from "react";
import {
  CheckboxButton as AriaCheckboxButton,
  type CheckboxButtonProps as AriaCheckboxButtonProps,
  CheckboxField as AriaCheckboxField,
  type CheckboxFieldProps as AriaCheckboxFieldProps,
  composeRenderProps,
  FieldError,
  Text,
  type ValidationResult,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import { fieldDescriptionStyles, fieldErrorStyles } from "./field-styles";

const CheckboxStateContext = createContext({
  isSelected: false,
  isIndeterminate: false,
  isHovered: false,
  isPressed: false,
});

export interface CheckboxProps
  extends Omit<AriaCheckboxFieldProps, "children"> {
  ref?: React.Ref<HTMLDivElement>;
  /** The label. Omit it and pass aria-label when the checkbox has no visible label. */
  children?: ReactNode;
  description?: ReactNode;
  errorMessage?: string | ((validation: ValidationResult) => string);
  checked?: boolean | "indeterminate";
  defaultChecked?: boolean | "indeterminate";
  onCheckedChange?: (checked: boolean) => void;
}

export function Checkbox({
  children,
  description,
  errorMessage,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: CheckboxProps) {
  // React Aria only supports a controlled indeterminate state. This keeps
  // defaultChecked="indeterminate" until the first change.
  const [defaultIndeterminate, setDefaultIndeterminate] = useState(
    defaultChecked === "indeterminate",
  );
  return (
    <CheckboxField
      {...props}
      isSelected={checked === undefined ? props.isSelected : checked === true}
      defaultSelected={
        defaultChecked === undefined
          ? props.defaultSelected
          : defaultChecked === true
      }
      isIndeterminate={
        checked === undefined
          ? props.isIndeterminate || defaultIndeterminate || undefined
          : checked === "indeterminate"
      }
      onChange={(isSelected) => {
        setDefaultIndeterminate(false);
        props.onChange?.(isSelected);
        onCheckedChange?.(isSelected);
      }}
    >
      <CheckboxButton>
        <CheckboxIndicator />
        {children != null && <CheckboxLabel>{children}</CheckboxLabel>}
      </CheckboxButton>
      {description != null && (
        <CheckboxDescription>{description}</CheckboxDescription>
      )}
      <CheckboxError>{errorMessage}</CheckboxError>
    </CheckboxField>
  );
}

export function CheckboxField({
  className,
  ...props
}: AriaCheckboxFieldProps & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaCheckboxField
      {...props}
      data-slot="checkbox"
      className={composeRenderProps(className, (className) =>
        cn(
          "relative inline-flex min-h-11 min-w-0 max-w-full flex-col justify-center gap-1 py-1 text-sm text-foreground disabled:opacity-50",
          className,
        ),
      )}
    />
  );
}

export function CheckboxButton({
  className,
  children,
  ...props
}: AriaCheckboxButtonProps & React.RefAttributes<HTMLLabelElement>) {
  return (
    <AriaCheckboxButton
      {...props}
      data-slot="checkbox-button"
      className={composeRenderProps(className, (className) =>
        cn(
          // The ::after layer stretches the hit area over the whole field,
          // so the description toggles the checkbox too.
          "group/checkbox flex min-w-0 cursor-pointer items-start gap-3 after:absolute after:inset-0 disabled:cursor-default read-only:cursor-default",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children, state) => (
        <CheckboxStateContext.Provider value={state}>
          {children}
        </CheckboxStateContext.Provider>
      ))}
    </AriaCheckboxButton>
  );
}

export function CheckboxIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isIndeterminate, isHovered, isPressed } =
    useContext(CheckboxStateContext);
  const reduceMotion = useReducedMotion();
  const isChecked = isSelected || isIndeterminate;
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="checkbox-indicator"
      className={cn(
        "grid size-5 shrink-0 place-items-center rounded-sm border border-muted-foreground/75 bg-card shadow-[var(--shadow-inset)] transition-[background-color,border-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover/checkbox:border-primary group-selected/checkbox:border-primary group-selected/checkbox:bg-primary group-indeterminate/checkbox:border-primary group-indeterminate/checkbox:bg-primary group-invalid/checkbox:border-destructive group-invalid/checkbox:group-hover/checkbox:border-destructive group-invalid/checkbox:group-selected/checkbox:bg-destructive group-focus-visible/checkbox:outline-2 group-focus-visible/checkbox:outline-offset-2 group-focus-visible/checkbox:outline-ring forced-colors:border-[ButtonText] forced-colors:group-selected/checkbox:border-[Highlight] forced-colors:group-selected/checkbox:bg-[Highlight] forced-colors:group-indeterminate/checkbox:border-[Highlight] forced-colors:group-indeterminate/checkbox:bg-[Highlight] forced-colors:group-disabled/checkbox:border-[GrayText] forced-colors:group-disabled/checkbox:bg-[Canvas]",
        className,
      )}
    >
      <motion.span
        initial={false}
        animate={{
          scale: isChecked ? (isPressed ? 0.9 : isHovered ? 1.06 : 1) : 0.86,
          opacity: isChecked ? 1 : 0,
        }}
        transition={{
          duration: reduceMotion ? 0 : duration.fast,
          ease: easeOut,
        }}
        className="text-primary-foreground forced-colors:text-[HighlightText] forced-colors:group-disabled/checkbox:text-[GrayText]"
      >
        {isIndeterminate ? (
          <MinusIcon size={13} weight="bold" />
        ) : (
          <CheckIcon size={13} weight="bold" />
        )}
      </motion.span>
    </span>
  );
}

export function CheckboxLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-label"
      className={cn("min-w-0 font-medium [overflow-wrap:anywhere]", className)}
    />
  );
}

export function CheckboxDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="checkbox-description"
      className={cn(fieldDescriptionStyles, "ps-8", className)}
    />
  );
}

export function CheckboxError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="checkbox-error"
      // relative keeps the message above the hit area layer.
      className={cn(fieldErrorStyles, "relative ps-8", className)}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  createContext,
  type HTMLAttributes,
  type ReactNode,
  useContext,
} from "react";
import {
  RadioButton as AriaRadioButton,
  type RadioButtonProps as AriaRadioButtonProps,
  RadioField as AriaRadioField,
  type RadioFieldProps as AriaRadioFieldProps,
  RadioGroup as AriaRadioGroup,
  type RadioGroupProps as AriaRadioGroupProps,
  composeRenderProps,
  FieldError,
  Label,
  Text,
  type ValidationResult,
} from "react-aria-components";
import { tv, type VariantProps } from "tailwind-variants";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import { fieldDescriptionStyles, fieldErrorStyles } from "./field-styles";

const radioFieldStyles = tv({
  base: "relative flex min-h-11 min-w-0 flex-col justify-center gap-1 py-1 text-sm text-foreground disabled:opacity-50",
  variants: {
    variant: {
      default: "",
      card: "min-h-14 rounded-lg bg-card px-4 py-3 shadow-[var(--shadow-card)] ring-1 ring-border transition-[background-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] has-[[data-hovered]]:bg-muted has-[[data-focus-visible]]:outline-2 has-[[data-focus-visible]]:outline-offset-2 has-[[data-focus-visible]]:outline-ring selected:bg-accent selected:ring-primary/40 invalid:ring-destructive/60 forced-colors:border forced-colors:selected:border-[Highlight]",
    },
  },
  defaultVariants: { variant: "default" },
});

type RadioVariant = NonNullable<
  VariantProps<typeof radioFieldStyles>["variant"]
>;

const RadioVariantContext = createContext<RadioVariant>("default");

const RadioStateContext = createContext({
  isSelected: false,
  isHovered: false,
  isPressed: false,
});

export interface RadioGroupProps extends Omit<AriaRadioGroupProps, "children"> {
  ref?: React.Ref<HTMLDivElement>;
  label?: ReactNode;
  description?: ReactNode;
  errorMessage?: string | ((validation: ValidationResult) => string);
  children: ReactNode;
  onValueChange?: (value: string) => void;
}

export function RadioGroup({
  label,
  description,
  errorMessage,
  className,
  children,
  onValueChange,
  ...props
}: RadioGroupProps) {
  return (
    <AriaRadioGroup
      {...props}
      data-slot="radio-group"
      onChange={(value) => {
        props.onChange?.(value);
        onValueChange?.(value);
      }}
      className={composeRenderProps(className, (className) =>
        cn(
          "group/radio-group flex min-w-0 flex-col gap-1 data-[orientation=horizontal]:flex-row data-[orientation=horizontal]:flex-wrap data-[orientation=horizontal]:gap-x-6",
          className,
        ),
      )}
    >
      {label != null && <RadioGroupLabel>{label}</RadioGroupLabel>}
      {description != null && (
        <RadioGroupDescription>{description}</RadioGroupDescription>
      )}
      {children}
      {(label != null || description != null || errorMessage != null) && (
        <RadioGroupError>{errorMessage}</RadioGroupError>
      )}
    </AriaRadioGroup>
  );
}

export function RadioGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="radio-group-label"
      className={cn(
        "w-full pb-1 text-sm font-semibold text-foreground [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function RadioGroupDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="radio-group-description"
      className={cn(
        fieldDescriptionStyles,
        "w-full pb-1 [[data-slot=radio-group-label]+&]:-mt-1",
        className,
      )}
    />
  );
}

export function RadioGroupItems({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="radio-group-items"
      className={cn(
        "flex w-full flex-col gap-1 group-data-[orientation=horizontal]/radio-group:flex-row group-data-[orientation=horizontal]/radio-group:flex-wrap group-data-[orientation=horizontal]/radio-group:gap-x-6",
        className,
      )}
    />
  );
}

export function RadioGroupError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="radio-group-error"
      className={cn(fieldErrorStyles, "w-full", className)}
    />
  );
}

export interface RadioProps extends Omit<RadioFieldProps, "children"> {
  /** The label. Omit it and pass aria-label when the option has no visible label. */
  children?: ReactNode;
  description?: ReactNode;
}

export function Radio({ children, description, ...props }: RadioProps) {
  return (
    <RadioField {...props}>
      <RadioButton>
        <RadioIndicator />
        {children != null && <RadioLabel>{children}</RadioLabel>}
      </RadioButton>
      {description != null && (
        <RadioDescription>{description}</RadioDescription>
      )}
    </RadioField>
  );
}

export interface RadioFieldProps extends AriaRadioFieldProps {
  ref?: React.Ref<HTMLDivElement>;
  variant?: RadioVariant;
}

export function RadioField({
  variant = "default",
  className,
  ...props
}: RadioFieldProps) {
  return (
    <RadioVariantContext.Provider value={variant}>
      <AriaRadioField
        {...props}
        data-slot="radio"
        data-variant={variant}
        className={composeRenderProps(className, (className) =>
          radioFieldStyles({ variant, className }),
        )}
      />
    </RadioVariantContext.Provider>
  );
}

export function RadioButton({
  className,
  children,
  ...props
}: AriaRadioButtonProps & React.RefAttributes<HTMLLabelElement>) {
  return (
    <AriaRadioButton
      {...props}
      data-slot="radio-button"
      className={composeRenderProps(className, (className) =>
        cn(
          // The ::after layer stretches the hit area over the whole field,
          // so the description and card padding select the option too.
          "group/radio flex min-w-0 cursor-pointer items-start gap-3 after:absolute after:inset-0 disabled:cursor-default read-only:cursor-default",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children, state) => (
        <RadioStateContext.Provider value={state}>
          {children}
        </RadioStateContext.Provider>
      ))}
    </AriaRadioButton>
  );
}

export function RadioIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const variant = useContext(RadioVariantContext);
  const { isSelected, isHovered, isPressed } = useContext(RadioStateContext);
  const reduceMotion = useReducedMotion();
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="radio-indicator"
      className={cn(
        "grid size-5 shrink-0 place-items-center rounded-full border border-muted-foreground/75 bg-card shadow-[var(--shadow-inset)] transition-[border-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover/radio:border-primary group-selected/radio:border-primary group-invalid/radio:border-destructive group-invalid/radio:group-hover/radio:border-destructive forced-colors:border-[ButtonText] forced-colors:group-selected/radio:border-[Highlight] forced-colors:group-disabled/radio:border-[GrayText]",
        // Card radios show the focus ring around the whole card instead.
        variant === "default" &&
          "group-focus-visible/radio:outline-2 group-focus-visible/radio:outline-offset-2 group-focus-visible/radio:outline-ring",
        className,
      )}
    >
      <motion.span
        initial={false}
        animate={{
          scale: isSelected ? (isPressed ? 0.85 : isHovered ? 1.12 : 1) : 0.86,
          opacity: isSelected ? 1 : 0,
        }}
        transition={{
          duration: reduceMotion ? 0 : duration.fast,
          ease: easeOut,
        }}
        className="size-2 rounded-full bg-primary forced-colors:bg-[Highlight] forced-colors:group-disabled/radio:bg-[GrayText]"
      />
    </span>
  );
}

export function RadioLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
