"use client";

import { motion, useReducedMotion } from "motion/react";
import { createContext, type ReactNode, useContext } from "react";
import {
  SwitchButton as AriaSwitchButton,
  type SwitchButtonProps as AriaSwitchButtonProps,
  SwitchField as AriaSwitchField,
  type SwitchFieldProps as AriaSwitchFieldProps,
  composeRenderProps,
  FieldError,
  Text,
  useLocale,
  type ValidationResult,
} from "react-aria-components";
import { springSnappy, transitionFor } from "./motion";
import { cn } from "./utils";
import { fieldDescriptionStyles, fieldErrorStyles } from "./field-styles";

const SwitchStateContext = createContext({
  isSelected: false,
  isPressed: false,
  isDisabled: false,
});

export interface SwitchProps extends Omit<AriaSwitchFieldProps, "children"> {
  ref?: React.Ref<HTMLDivElement>;
  /** The label. Omit it and pass aria-label when the switch has no visible label. */
  children?: ReactNode;
  description?: ReactNode;
  errorMessage?: string | ((validation: ValidationResult) => string);
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

export function Switch({
  children,
  description,
  errorMessage,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: SwitchProps) {
  return (
    <SwitchField
      {...props}
      isSelected={checked ?? props.isSelected}
      defaultSelected={defaultChecked ?? props.defaultSelected}
      onChange={(isSelected) => {
        props.onChange?.(isSelected);
        onCheckedChange?.(isSelected);
      }}
    >
      <SwitchButton>
        {children != null && <SwitchLabel>{children}</SwitchLabel>}
        <SwitchControl>
          <SwitchThumb />
        </SwitchControl>
      </SwitchButton>
      {description != null && (
        <SwitchDescription>{description}</SwitchDescription>
      )}
      <SwitchError>{errorMessage}</SwitchError>
    </SwitchField>
  );
}

export function SwitchField({
  className,
  ...props
}: AriaSwitchFieldProps & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaSwitchField
      {...props}
      data-slot="switch"
      className={composeRenderProps(className, (className) =>
        cn(
          "relative inline-grid min-h-11 min-w-0 max-w-full grid-cols-[minmax(0,1fr)_auto] content-center items-center py-1 text-sm text-foreground disabled:opacity-50",
          className,
        ),
      )}
    />
  );
}

export function SwitchButton({
  className,
  children,
  ...props
}: AriaSwitchButtonProps & React.RefAttributes<HTMLLabelElement>) {
  return (
    <AriaSwitchButton
      {...props}
      data-slot="switch-button"
      className={composeRenderProps(className, (className) =>
        cn(
          // Spans the label and description rows so the control centers on
          // both. The ::after layer makes the whole field the hit area.
          "group/switch col-span-full row-[1/span_2] grid cursor-pointer grid-cols-subgrid grid-rows-subgrid items-center after:absolute after:inset-0 disabled:cursor-default read-only:cursor-default",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children, state) => (
        <SwitchStateContext.Provider value={state}>
          {children}
        </SwitchStateContext.Provider>
      ))}
    </AriaSwitchButton>
  );
}

export function SwitchLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="switch-label"
      className={cn(
        "me-4 min-w-0 font-medium [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function SwitchDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="switch-description"
      className={cn(
        fieldDescriptionStyles,
        "col-start-1 row-start-2 me-4 mt-1",
        className,
      )}
    />
  );
}

export function SwitchError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="switch-error"
      // relative keeps the message above the hit area layer.
      className={cn(
        fieldErrorStyles,
        "relative col-span-full row-start-3 mt-1",
        className,
      )}
    />
  );
}

export function SwitchControl({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="switch-control"
      className={cn(
        "row-span-2 flex h-6 w-10 shrink-0 items-center rounded-full bg-muted-foreground/75 p-0.5 shadow-[var(--shadow-inset)] transition-colors duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover/switch:bg-muted-foreground group-selected/switch:bg-primary group-selected/switch:group-hover/switch:bg-primary/90 group-invalid/switch:ring-2 group-invalid/switch:ring-destructive group-focus-visible/switch:outline-2 group-focus-visible/switch:outline-solid group-focus-visible/switch:outline-offset-2 group-focus-visible/switch:outline-ring forced-colors:border forced-colors:border-[ButtonText] forced-colors:p-px forced-colors:group-selected/switch:border-[Highlight] forced-colors:group-disabled/switch:border-[GrayText]",
        className,
      )}
    />
  );
}

export function SwitchThumb({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isPressed, isDisabled } = useContext(SwitchStateContext);
  const { direction } = useLocale();
  const reduceMotion = useReducedMotion();
  const width = !isDisabled && isPressed ? 24 : 20;
  const travel = 36 - width;
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="switch-thumb"
      className={cn("contents", className)}
    >
      <motion.span
        initial={false}
        animate={{
          x: isSelected ? (direction === "rtl" ? -travel : travel) : 0,
          width,
        }}
        transition={transitionFor(reduceMotion, springSnappy)}
        className="size-5 shrink-0 rounded-full bg-card shadow-[var(--shadow-card)] transition-colors duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] group-selected/switch:bg-primary-foreground forced-colors:bg-[ButtonText] forced-colors:group-selected/switch:bg-[Highlight] forced-colors:group-disabled/switch:bg-[GrayText]"
      />
    </span>
  );
}

"use client";

import { useState } from "react";
import { Button } from "../../../components/vip-ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../../../components/vip-ui/card";
import { Checkbox } from "../../../components/vip-ui/checkbox";
import { Radio, RadioGroup } from "../../../components/vip-ui/radio-group";
import { Switch } from "../../../components/vip-ui/switch";

const channels = ["Email", "Push", "Slack"] as const;
type Channel = (typeof channels)[number];

const events = [
  { id: "mentions", label: "Mentions", description: "Someone tags you." },
  { id: "comments", label: "Comments", description: "On items you follow." },
  { id: "assigned", label: "Assignments", description: "A task is yours." },
  { id: "deploys", label: "Failed deploys", description: "A build stops." },
  { id: "summary", label: "Weekly summary", description: "Each Monday." },
] as const;
type EventId = (typeof events)[number]["id"];

const initialMatrix: Record<EventId, Channel[]> = {
  mentions: ["Email", "Push", "Slack"],
  comments: ["Push"],
  assigned: ["Email", "Slack"],
  deploys: ["Email", "Push", "Slack"],
  summary: ["Email"],
};

export function NotificationSettings() {
  const [matrix, setMatrix] = useState(initialMatrix);
  const [paused, setPaused] = useState(false);
  const [saved, setSaved] = useState(false);

  function toggle(event: EventId, channel: Channel, on: boolean) {
    setSaved(false);
    setMatrix((current) => ({
      ...current,
      [event]: on
        ? [...current[event], channel]
        : current[event].filter((item) => item !== channel),
    }));
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle as="h1" className="text-xl">
          Notifications
        </CardTitle>
        <CardDescription>
          Choose where we tell you about each event.
        </CardDescription>
      </CardHeader>
      <CardContent className="grid gap-6">
        <Switch
          checked={paused}
          onCheckedChange={(value) => {
            setSaved(false);
            setPaused(value);
          }}
          description="We keep all events and send nothing until you turn this off."
          className="w-full rounded-lg bg-muted/60 px-4 py-3 ring-1 ring-border/70"
        >
          Pause all notifications
        </Switch>
        <div className="-mx-6 overflow-x-auto px-6">
          <table className="w-full min-w-[420px] border-separate border-spacing-0 text-sm">
            <caption className="sr-only">
              Notification channels for each event
            </caption>
            <thead>
              <tr>
                <th
                  scope="col"
                  className="border-b border-border pb-3 text-start text-xs font-semibold text-muted-foreground"
                >
                  Event
                </th>
                {channels.map((channel) => (
                  <th
                    key={channel}
                    scope="col"
                    className="w-20 border-b border-border pb-3 text-center text-xs font-semibold text-muted-foreground"
                  >
                    {channel}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {events.map((event) => (
                <tr key={event.id}>
                  <th
                    scope="row"
                    className="border-b border-border/70 py-3 pe-4 text-start font-normal"
                  >
                    <span className="block font-medium">{event.label}</span>
                    <span className="block text-xs text-muted-foreground">
                      {event.description}
                    </span>
                  </th>
                  {channels.map((channel) => (
                    <td
                      key={channel}
                      className="border-b border-border/70 text-center"
                    >
                      <Checkbox
                        aria-label={`${event.label} by ${channel}`}
                        isDisabled={paused}
                        checked={matrix[event.id].includes(channel)}
                        onCheckedChange={(on) => toggle(event.id, channel, on)}
                        className="w-full items-center"
                      />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <RadioGroup
          label="Email delivery"
          defaultValue="hourly"
          isDisabled={paused}
          onChange={() => setSaved(false)}
        >
          <Radio value="instant">Right away</Radio>
          <Radio
            value="hourly"
            description="One email with all events from the last hour."
          >
            Once an hour
          </Radio>
          <Radio
            value="daily"
            description="One email at 9:00 in your time zone."
          >
            Once a day
          </Radio>
        </RadioGroup>
      </CardContent>
      <CardFooter className="justify-end border-t border-border/70 pt-5">
        <output className="me-auto text-sm text-muted-foreground">
          {saved ? "Settings saved." : ""}
        </output>
        <Button
          variant="ghost"
          onPress={() => {
            setMatrix(initialMatrix);
            setPaused(false);
            setSaved(false);
          }}
        >
          Reset
        </Button>
        <Button onPress={() => setSaved(true)}>Save</Button>
      </CardFooter>
    </Card>
  );
}

